  List<int> results = [];

  List<int> A = List<int>.filled(n + 2, 0);
  A[0] = 1 << 30;  // A[0] = MAX_INT
  List<int> R = List<int>.filled(n + 2, 0);
  List<int> B = List<int>.filled(n + 2, 0);

  int N = 1;
  int count = 0;
  int? oldx;

  for (int i = 1; i <= n; i++) {
    int x = values[i - 1];

    if (i > 1 && (oldx == null || x != oldx)) {
      A[N] = count;
      R[N] = i;
      N++;
      count = 0;
    }

    B[i] = N;
    count++;
    oldx = x;
